// Test fixture content script. Writes observed API behaviour into the page so
// the Electron compatibility test can read it; it never sends data anywhere.
(async () => {
  const result = { contentApis: Object.keys(chrome).sort(), cookie: document.cookie };
  try {
    await chrome.storage.local.set({ probe: 'stored' });
    result.storage = (await chrome.storage.local.get('probe')).probe;
  } catch (error) { result.storage = `error: ${error.message}`; }
  try { result.worker = await chrome.runtime.sendMessage({ urls: JSON.parse(document.body.dataset.urls || '{}') }); }
  catch (error) { result.worker = `error: ${error.message}`; }
  document.documentElement.dataset.weftProbe = JSON.stringify(result);
})();

probe.service-worker.js:
// Test fixture service worker: exercises APIs and network paths for the
// Electron compatibility test and replies with what happened.
const attempt = async action => { try { return await action(); } catch (error) { return `error: ${error.message}`; } };
chrome.runtime.onMessage.addListener((message, sender, reply) => {
  (async () => {
    const urls = message.urls || {};
    const fetchStatus = url => attempt(async () => (await fetch(url, { cache: 'no-store' })).status);
    reply({
      workerApis: Object.keys(chrome).sort(),
      tabs: await attempt(async () => (await chrome.tabs.query({})).map(tab => tab.url)),
      scripting: await attempt(async () => (await chrome.scripting.executeScript({ target: { tabId: sender.tab.id }, func: () => location.pathname }))[0].result),
      nativeMessaging: await attempt(async () => { chrome.runtime.connectNative('com.example.native'); return 'connected'; }),
      cookies: typeof chrome.cookies,
      webRequest: typeof chrome.webRequest,
      debuggerApi: typeof chrome.debugger,
      fetchGranted: await fetchStatus(urls.granted),
      fetchSiteBlocked: await fetchStatus(urls.siteBlocked),
      fetchUngranted: await fetchStatus(urls.ungranted),
    });
  })();
  return true;
});

